/**
 * UI localisation. The reference editor ships one translation table per language; the strings below are
 * English → translated (src/data/i18n/<lang>.json, generated by tools/gen/i18n.py). The widget is built with
 * English strings; a Localizer rewrites `title` / `aria-label` / text of the built DOM (and of everything that
 * is added later) so the logic keeps working on the English wording.
 * The handwriting panel is not translated by the reference, so it is skipped.
 */
import ar from '../data/i18n/ar.json';

/** strings of the optional output panel (not part of the reference editor) */
const OUTPUT_AR: Record<string, string> = {
  'Output format': 'تنسيق الإخراج',
  Output: 'الإخراج',
  'Accessible text': 'نص قابل للوصول',
  'Plain text': 'نص عادي',
  Copy: 'نسخ',
  Download: 'تنزيل',
  Retry: 'إعادة المحاولة',
  Error: 'خطأ',
  'Copied to clipboard': 'تم النسخ إلى الحافظة',
  'Rendered formula': 'المعادلة المعروضة',
  'Move left': 'تحريك لليسار',
  'Move right': 'تحريك لليمين',
  'Move up': 'تحريك لأعلى',
  'Move down': 'تحريك لأسفل',
  'Move the cursor': 'تحريك المؤشر',
  'Clear the formula': 'مسح المعادلة',
  'Clear the whole formula?': 'هل تريد مسح المعادلة بالكامل؟',
  Clear: 'مسح',
  Cancel: 'إلغاء',
};

const TABLES: Record<string, Record<string, string>> = { ar: { ...ar, ...OUTPUT_AR } };

/** table for a language code ("ar", "ar_eg", "AR-sa" …), or undefined for English / unsupported languages */
export function tableFor(lang: string): Record<string, string> | undefined {
  const l = (lang || 'en').toLowerCase().replace('-', '_');
  return TABLES[l];
}

/** translate one UI string; unknown strings are returned unchanged */
export function translate(table: Record<string, string> | undefined, s: string): string {
  if (!table || !s) return s;
  const hit = table[s];
  if (hit !== undefined) return hit;
  // "Fraction (Ctrl+/)" → translated name + the untranslated shortcut
  let m = /^(.*?)(\s*\([^()]*\))$/.exec(s);
  if (m && table[m[1]] !== undefined) return table[m[1]] + m[2];
  // "Rows:" → "صفوف:"
  m = /^(.*?)(\s*:\s*)$/.exec(s);
  if (m && table[m[1]] !== undefined) return table[m[1]] + m[2];
  return s;
}

const ATTRS = ['title', 'aria-label', 'placeholder', 'alt'];
const EN_PREFIX = 'data-en-';

export class Localizer {
  private obs: MutationObserver | null = null;
  private busy = false;

  constructor(
    private readonly table: Record<string, string> | undefined,
    private readonly skip: (el: Element) => boolean = () => false,
  ) {}

  get active(): boolean {
    return !!this.table;
  }

  /** the English wording of an element's title (the DOM holds the translation) */
  static english(el: Element, attr = 'title'): string {
    return el.getAttribute(EN_PREFIX + attr) ?? el.getAttribute(attr) ?? '';
  }

  /** translate a subtree now and keep translating what is added to it */
  attach(root: HTMLElement): void {
    if (!this.table) return;
    this.apply(root);
    this.obs = new MutationObserver((records) => {
      if (this.busy) return;
      this.busy = true;
      try {
        for (const r of records) {
          if (r.type === 'attributes') {
            if (r.target instanceof Element) this.element(r.target);
          } else if (r.type === 'characterData') {
            if (r.target.parentElement && !this.skip(r.target.parentElement)) this.text(r.target as Text);
          } else r.addedNodes.forEach((n) => this.apply(n));
        }
      } finally {
        this.busy = false;
      }
    });
    this.obs.observe(root, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: ATTRS });
  }

  detach(): void {
    this.obs?.disconnect();
    this.obs = null;
  }

  apply(node: Node): void {
    if (!this.table) return;
    if (node.nodeType === 3) {
      if (node.parentElement && !this.skip(node.parentElement) && !this.inSkipped(node.parentElement)) this.text(node as Text);
      return;
    }
    if (!(node instanceof Element) || this.inSkipped(node)) return;
    this.element(node);
    for (const c of Array.from(node.childNodes)) this.apply(c);
  }

  private inSkipped(el: Element): boolean {
    for (let e: Element | null = el; e; e = e.parentElement) if (this.skip(e) || e.tagName === 'svg' || e.tagName === 'TEXTAREA' || e.tagName === 'SCRIPT' || e.tagName === 'STYLE') return true;
    return false;
  }

  private element(el: Element): void {
    if (this.inSkipped(el)) return;
    for (const a of ATTRS) {
      const v = el.getAttribute(a);
      if (!v) continue;
      const en = el.getAttribute(EN_PREFIX + a);
      // the attribute was rewritten by the widget with new English text → translate again
      const src = en !== null && v === translate(this.table, en) ? en : v;
      const t = translate(this.table, src);
      if (t !== v) {
        el.setAttribute(EN_PREFIX + a, src);
        el.setAttribute(a, t);
      } else if (en !== null && v === en) {
        el.removeAttribute(EN_PREFIX + a);
      }
    }
  }

  private text(n: Text): void {
    const v = n.nodeValue ?? '';
    const trimmed = v.trim();
    if (!trimmed) return;
    const t = translate(this.table, trimmed);
    if (t !== trimmed) n.nodeValue = v.replace(trimmed, t);
  }
}
